#include <iostream>
#include <string>
#include <vector>

int main() {
    std::vector<int> lecturas{-4, 0, 7, 10, -5};
    int validas{0};
    int rechazadas{0};
    int suma{0};
    for (int lectura : lecturas) {
        std::cout << "Lecture=" << lectura << ":";
        if (lectura < -4 || lectura > 9) {
            ++rechazadas;
            std::cout << "Hors limites\n";
        } else {
            ++validas;
            suma += lectura;
            if (lectura < 0) {
                std::cout << "Froide\n";
            } else if (lectura == 0) {
                std::cout << "Neutre\n";
            } else {
                std::cout << "Chaude\n";
            }
        }
    }
    std::cout << "Résumé=" << validas << ":" << rechazadas << ":" << suma;
    return 0;
}

