#include <iostream>
#include <string>
#include <vector>

// Reçoit un relevé valide de -4 à 9 ; renvoie son étiquette sans afficher.
std::string etiqueta_de_lectura(int lectura) {
    if (lectura < 0) { return "Froide"; }
    if (lectura == 0) { return "Neutre"; }
    return "Chaude";
}

int main() {
    std::vector<int> lecturas{9, -5, -1, 0};
    int validas{0};
    int rechazadas{0};
    int suma{0};
    for (int lectura : lecturas) {
        std::cout << "Lecture=" << lectura << ":";
        if (lectura < -4 || lectura > 9) {
            ++rechazadas;
            std::cout << "Hors limites\n";
        } else {
            ++validas;
            suma += lectura;
            std::cout << etiqueta_de_lectura(lectura) << "\n";
        }
    }
    std::cout << "Résumé=" << validas << ":" << rechazadas << ":" << suma;
    return 0;
}

